<template>
  <div class="prepare-page" data-test="prepare-dashboard-page">
    <!-- Top bar with logo -->
    <div class="prepare-topbar">
      <q-img src="/images/docbits.svg" class="topbar-logo" />
    </div>

    <!-- Main content area -->
    <div class="prepare-main">
      <!-- Cross-region switch banner: shown on the NORMAL prepare screen (with
           the videos + step chips below it) after we reroute the user to the
           cluster their profile lives on, and kept visible for the whole
           prepare flow so it isn't washed away by the reload (DOCB-12864). -->
      <div v-if="showRegionBanner" class="region-banner" data-test="region-switch">
        <img
          v-if="switchAnimationSrc"
          :src="switchAnimationSrc"
          alt=""
          class="region-banner-anim"
          data-test="region-switch-animation"
        />
        <div class="region-banner-text">
          <span class="region-banner-title">{{ $t('region_redirect_title') }}</span>
          <span class="region-banner-message" data-test="region-switch-message">
            {{ $t('region_redirect_message', { profile: switchTargetLabel }) }}
          </span>
        </div>
      </div>

      <!-- Loading state while language initializes -->
      <div v-if="!languageReady" class="prepare-loading-spinner" data-test="preparing-spinner">
        <q-spinner-dots color="primary" size="50px" />
      </div>

      <template v-else>
        <!-- Header: title + subtitle -->
        <div class="prepare-header">
          <h1 class="prepare-title">{{ $t('preparing_dashboard') }}</h1>
          <p class="prepare-subtitle">{{ progressSubtitle }}</p>
        </div>

        <!-- Wide progress bar -->
        <div class="prepare-progress">
          <q-linear-progress
            :value="progressValue"
            color="primary"
            size="8px"
            class="prepare-progress-bar"
            rounded
            data-test="initialization-progress"
          />
          <div class="prepare-progress-info">
            <span class="progress-percent">{{ Math.round(progressValue * 100) }}%</span>
            <span class="progress-step">{{ currentStepText }}</span>
            <span class="progress-time" v-if="estimatedSeconds > 0">
              ~{{ estimatedSeconds }}s {{ $t('remaining') }}
            </span>
          </div>
        </div>

        <!-- Signal for Playwright that initialization is finished -->
        <div v-if="progressValue === 1" data-test="initialization-complete" style="display:none"></div>

        <!-- Video Carousel (hidden on small screens) -->
        <div class="prepare-carousel" v-if="!errorMessage && !hasFailedCritically">
          <div class="prepare-carousel-header">
            <HelpLink name="video_carousel" data-test="help-link-video-carousel" />
          </div>
          <VideoCarousel @user-interact="onCarouselInteract" />
        </div>

        <!-- Loading icon fallback for small screens (no carousel) -->
        <div class="prepare-mobile-icon" v-if="!errorMessage && !hasFailedCritically">
          <img src="~src/icons/docbits-loading-orbit.svg" alt="" class="mobile-loading-icon" />
        </div>

        <!-- Steps as horizontal pills -->
        <div class="prepare-steps">
          <div
            v-for="(step, index) in steps"
            :key="index"
            class="step-pill"
            :class="{
              'pill-completed': step.isCompleted,
              'pill-active': !step.isCompleted && !step.hasError && isCurrentStep(index),
              'pill-pending': !step.isCompleted && !step.hasError && !isCurrentStep(index),
              'pill-error': step.hasError,
            }"
          >
            <Icon
              v-if="step.isCompleted && !step.hasError"
              icon="mdi:check-circle-outline"
              class="size-3.5"
            />
            <Icon
              v-else-if="step.hasError"
              icon="mdi:close-circle-outline"
              class="size-3.5"
            />
            <q-spinner-dots
              v-else-if="isCurrentStep(index)"
              color="primary"
              size="14px"
            />
            <span v-else class="pill-pending-dot"></span>
            <span class="pill-text">{{ $t(step.stepName) }}</span>
          </div>
        </div>

        <!-- Timeout Warning -->
        <div
          v-if="showTimeoutWarning && !errorMessage && !hasFailedCritically"
          class="prepare-warning"
        >
          <Icon icon="mdi:clock-alert-outline" class="size-4 text-amber-600 dark:text-amber-400" />
          <span>{{ $t('timeout_message') }}</span>
        </div>

        <!-- Error Display -->
        <div v-if="errorMessage || hasFailedCritically" class="prepare-error" data-test="prepare-dashboard-error">
          <div class="error-banner-inline">
            <Icon icon="mdi:alert-circle-outline" class="size-5 text-destructive" />
            <span>{{ errorMessage || $t('critical_error') }}</span>
          </div>
          <div class="error-actions">
            <q-btn
              :label="$t('back_to_login')"
              unelevated
              no-caps
              class="f-btn action-btn"
              @click="goToLogin"
            />
            <q-btn
              :label="$t('dashboard_setup_retry')"
              outline
              no-caps
              class="f-btn action-btn"
              @click="retrySetup"
              v-if="!isInitializing"
            />
          </div>
        </div>

        <!-- Continue to Dashboard button -->
        <q-btn
          v-if="!errorMessage && !hasFailedCritically && progressValue === 1 && (userInteractedWithCarousel || isTestEnvironment)"
          :label="$t('continue_to_dashboard')"
          color="primary"
          unelevated
          no-caps
          class="continue-btn"
          data-test="continue-to-dashboard-btn"
          @click="performRedirect"
        />
      </template>
    </div>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { Acl, Cache as Acl_Cache } from 'src/core/acls/index';
import { defineComponent } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions/index';
import { isUndefinedOrNull } from 'src/utils/general';
import { userApiService } from 'src/services';
import { authSdkService } from 'src/services/user/authSdkService';
import {
  useUserStore,
  useSettingStore,
  useSubscriptionStore,
  useDashboardPreloadStore,
} from 'src/store/main';
import { useAuthTokenStore } from 'src/store/User/auth_token.store';
import subscriptionUtil from 'src/utils/subscriptionUtil';
import { tol } from 'src/boot/tolgee';
import { LocalStorage, SessionStorage } from 'quasar';
import logger from 'src/utils/logger';
import { CONSTANTS, preferred_language_setting } from 'src/constants';
import { cacheDataAfterLogin } from 'src/utils/dataCache';
import {
  api,
  getCurrentAuthRegion,
  isRegionalStage,
  setApiRegion,
  setAuthRegion,
  type ApiRegion,
} from 'pages/APIs';
import {
  MAX_SYNC_ATTEMPTS,
  probeProfileReady,
  regionFromOrgs,
  regionSwitchTarget,
  sleep,
  switchAnimationAsset,
  syncRetryDelayMs,
} from 'src/utils/region-sync';
import { getUserDetailFromkey } from 'src/utils/UserDetails';
import { getOrgId } from 'src/utils/organization/org_id_helper';
import VideoCarousel from 'src/components/VideoCarousel/VideoCarousel.vue';

const _AFTER_LOGIN_ROUTE_KEY = 'after_login_route';
// Survives the cross-region hard-reload: presence means a switch is in flight,
// so the post-reload mount runs the retry loop instead of re-detecting.
const REGION_SWITCH_KEY = 'region_switch';
let _mountCount = 0;

interface RegionSwitchRecord {
  from: ApiRegion;
  to: ApiRegion;
}

export default defineComponent({
  components: { VideoCarousel },

  data() {
    return {
      languageReady: false as boolean,
      showRegionBanner: false as boolean,
      switchFrom: null as ApiRegion | null,
      switchTo: null as ApiRegion | null,
      userInteractedWithCarousel: false,
      steps: [
        { stepName: 'step_securing_login', isCompleted: false, hasError: false },
        { stepName: 'step_loading_settings', isCompleted: false, hasError: false },
        { stepName: 'step_preparing_workspace', isCompleted: false, hasError: false },
        { stepName: 'step_confirming_access', isCompleted: false, hasError: false },
        { stepName: 'step_preparing_data', isCompleted: false, hasError: false },
        { stepName: 'step_almost_ready', isCompleted: false, hasError: false },
      ] as Array<{ stepName: string; isCompleted: boolean; hasError: boolean }>,
      errorMessage: '' as string,
      isInitializing: false as boolean,
      hasFailedCritically: false as boolean,
      estimatedSeconds: 15 as number,
      totalEstimatedTime: 15,
      startTime: 0 as number,
      timerInterval: null as ReturnType<typeof setInterval> | null,
      showTimeoutWarning: false as boolean,
    };
  },
  async mounted() {
    await this.initLanguage();
    this.languageReady = true;
    this.startTimer();

    // Router guard at src/router/index.ts already validates the token (isLoggedIn)
    // before allowing entry to /prepare-dashboard, so we don't re-check here.

    _mountCount++;
    if (_mountCount > 3) {
      logger.error('PrepareDashboard: Infinite reload loop detected, blocking initialization');
      this.hasFailedCritically = true;
      this.errorMessage =
        'Infinite reload loop detected. This usually happens when there are authentication or API connection issues.';
      return;
    }

    // Cross-region reconciliation owns the region BEFORE the normal pipeline
    // (DOCB-12864). On a region mismatch it persists the target region and
    // hard-reloads; on the post-reload mount it runs the retry loop until the
    // target cluster's auth accepts the token. Returns false when the caller
    // must stop here (a reload was triggered, or the switch gave up). Running
    // this before the token gate gives the new cluster time to accept the token.
    const proceed = await this.reconcileRegion();
    if (!proceed) return;

    // Layer 2: Proactive token validation before starting setup
    // Ensures token is fresh BEFORE any setup API calls start
    // This prevents 401 errors during the multi-step initialization process
    const auth_token_store = useAuthTokenStore();
    const hasValidToken = await auth_token_store.isLoggedIn();

    if (!hasValidToken) {
      logger.error('[PrepareDashboard] Token validation failed - session expired or invalid');
      this.hasFailedCritically = true;
      this.errorMessage = 'Session validation failed. Please log in again.';
      return;
    }

    logger.info('[PrepareDashboard] Token validated successfully, proceeding with setup');
    this.initPage();
  },
  beforeUnmount() {
    if (this.timerInterval) {
      clearInterval(this.timerInterval);
    }
  },
  methods: {
    // Returns true when the caller should proceed to the normal setup pipeline,
    // false when it must stop (a hard-reload was triggered, or the switch gave up).
    async reconcileRegion(): Promise<boolean> {
      if (!isRegionalStage()) return true;

      if (this.isRegionSwitchInFlight()) {
        return this.completeRegionSwitch();
      }
      return this.detectAndStartRegionSwitch();
    },

    async detectAndStartRegionSwitch(): Promise<boolean> {
      try {
        // currentRegion is the auth host the JUST-COMPLETED login actually
        // authenticated against (Login.vue's finishLogin() calls
        // setAuthRegion(regionForLogin) before ever reaching this page), so
        // it is read BEFORE the profile probe and passed to getProfile()
        // explicitly below — NOT left to the module-load-time-frozen
        // `api.get_profile` host (DOCB-13989 round 2). On a fresh session that
        // frozen host is whatever getCurrentAuthRegion() returned when
        // api-base-url.ts first loaded (i.e. BEFORE the user ever touched the
        // login region dropdown) — for a brand-new session with nothing in
        // LocalStorage yet that's always the 'eu' default. When the user
        // actually logged in against the other region (e.g. picked 'us'), a
        // region-less probe queried the wrong cluster relative to where the
        // token was issued, got a same-region-mismatch 401 that could never
        // turn into a 200, and — because getProfile() swallows 401 into `{}`
        // — silently reported "no organisations", so the mismatch this whole
        // function exists to detect was NEVER found and no switch/reload
        // ever fired. The user was left stranded on prepare-dashboard.
        const currentRegion = getCurrentAuthRegion();

        // Bounded: a stalled profile probe must not strand the page on a
        // spinner — on timeout the catch below falls through to the normal
        // pipeline (which has its own retry/error UX).
        const profile = await this.withTimeout(
          userApiService.getProfile(currentRegion),
          8000,
          'Region probe timeout',
        );
        const orgs = Array.isArray(profile?.organisations)
          ? profile.organisations
          : [];
        // Active org (post select-org/switch-org this is the org the user
        // just chose, not necessarily their default — SD Befund B8) drives
        // the region, so a mid-session switch to a different-region org is
        // reconciled the same way a cross-region login already is.
        const target = regionSwitchTarget(
          currentRegion,
          regionFromOrgs(orgs, getOrgId()),
        );
        if (!target) return true;

        this.startRegionSwitch(currentRegion, target);
        return false;
      } catch (err) {
        // Detection is non-fatal: fall through to the normal pipeline, which has
        // its own retry/error handling.
        logger.info('[PrepareDashboard] region reconciliation skipped', err);
        return true;
      }
    },

    startRegionSwitch(from: ApiRegion, to: ApiRegion) {
      SessionStorage.set(REGION_SWITCH_KEY, { from, to });
      // Persist the target region, then hard-reload so every module-load-time
      // URL constant (AUTH_URL, DOC2API_URL, …) rebuilds against the new prefix.
      // The banner is shown by the post-reload mount (completeRegionSwitch), not
      // here — anything painted now is wiped by the reload.
      setAuthRegion(to);
      setApiRegion(to);
      if (typeof window !== 'undefined') {
        window.location.reload();
      }
    },

    async completeRegionSwitch(): Promise<boolean> {
      const record = this.readSwitchRecord();
      if (!record) return true;

      // Show the banner immediately and keep it up for the rest of the prepare
      // flow (we never flip it back off) so the user actually reads it instead
      // of it flashing past during the reload.
      this.switchFrom = record.from;
      this.switchTo = record.to;
      this.showRegionBanner = true;

      for (let attempt = 1; attempt <= MAX_SYNC_ATTEMPTS; attempt += 1) {
        if (await probeProfileReady()) {
          SessionStorage.remove(REGION_SWITCH_KEY);
          return true;
        }
        if (attempt === MAX_SYNC_ATTEMPTS) {
          logger.warn('[PrepareDashboard] region switch gave up after retries');
          SessionStorage.remove(REGION_SWITCH_KEY);
          this.hasFailedCritically = true;
          this.errorMessage = this.$t('region_redirect_timeout_message') as string;
          return false;
        }
        await sleep(syncRetryDelayMs(attempt));
      }
      return false;
    },

    isRegionSwitchInFlight(): boolean {
      return this.readSwitchRecord() !== null;
    },

    readSwitchRecord(): RegionSwitchRecord | null {
      const raw = SessionStorage.getItem(REGION_SWITCH_KEY) as
        | RegionSwitchRecord
        | null;
      if (!raw) return null;
      const valid = (r: unknown): r is ApiRegion => r === 'eu' || r === 'us';
      if (!valid(raw.from) || !valid(raw.to)) return null;
      return { from: raw.from, to: raw.to };
    },

    async initLanguage() {
      const selectedLanguage = LocalStorage.getItem(CONSTANTS.selected_language) as string;
      if (!selectedLanguage) return;

      const targetLang = selectedLanguage.split('-')[0];
      if (tol.getLanguage() === targetLang) return;

      try {
        await tol.changeLanguage(targetLang);
      } catch {
        // Language change failed — continue with default.
      }
    },

    async applyBackendLanguage() {
      // Backend PREFERRED_LANGUAGE wins. On a fresh login the app boots before
      // the auth token exists, so boot's restoreBackendLanguage() bailed and
      // `selected_language` still holds the login-page choice. Called from
      // initPage() AFTER step 3, the server preference is already in the store
      // (this reads it — no extra GET). Keep the regional setting code in sync
      // so the language picker highlights the active option on the dashboard.
      try {
        const backendLanguage = await useSettingStore().getUserBasedSettings(preferred_language_setting) as string | undefined;
        if (!backendLanguage) return; // no server preference — keep current

        LocalStorage.set(CONSTANTS.selected_language, backendLanguage);
        const targetLang = backendLanguage.split('-')[0];
        if (tol.getLanguage() !== targetLang) {
          await tol.changeLanguage(targetLang);
        }
      } catch {
        // Non-fatal: keep the language already applied by initLanguage().
      }
    },

    startTimer() {
      this.startTime = Date.now();
      this.timerInterval = setInterval(() => {
        const elapsed = Math.floor((Date.now() - this.startTime) / 1000);
        const remaining = Math.max(0, this.totalEstimatedTime - elapsed);
        this.estimatedSeconds = remaining;

        // Show timeout warning after 20 seconds
        if (elapsed > 20 && !this.showTimeoutWarning) {
          this.showTimeoutWarning = true;
        }
      }, 1000);
    },

    isCurrentStep(index: number) {
      const completedCount = this.steps.filter((s) => s.isCompleted).length;
      return index === completedCount;
    },

    async initPage() {
      // Prevent multiple simultaneous executions
      if (this.isInitializing) {
        logger.info(
          'PrepareDashboard: Already initializing, skipping duplicate call',
        );
        return;
      }

      this.isInitializing = true;
      this.hasFailedCritically = false;

      try {
        // step 1: Load profile (populates user_details.id) then establish session.
        // Profile must run first so setUserSession has user_id to POST.
        try {
          await this.withRetry(
            () => this.withTimeout(useUserStore().getProfile(), 15000, 'Profile loading timeout'),
            'Loading user profile',
          );
          await authSdkService.setUserSession();
          this.steps[0].isCompleted = true;
        } catch (err) {
          this.handleStepError(0, 'Failed to secure session', err);
          return;
        }

        // step 2: ACL fetch (now that org_id is set by step 1).
        // Failure falls back to cached permissions from a previous session.
        try {
          await this.withRetry(
            () => this.withTimeout(Acl.fetch(), 10000, 'ACL fetch timeout'),
            'Loading ACL data',
          );
        } catch (aclError) {
          const cachedAcls = Acl_Cache.get();
          if (cachedAcls && Object.keys(cachedAcls).length > 0) {
            logger.warn('PrepareDashboard: ACL fetch failed, using cached permissions', aclError);
            notify.warning(
              'Using cached permissions from previous session. Some features may not be up to date.',
              { duration: 8000 },
            );
          } else {
            this.handleStepError(1, 'Failed to load user permissions', aclError);
            return;
          }
        }
        this.steps[1].isCompleted = true;

        // step 3: Settings + organizations in parallel
        // Both only need org_id and (for supplier admins) user_details from step 2.
        try {
          await Promise.all([
            this.withRetry(
              () => this.withTimeout(useSettingStore().startSettingsFetch(), 15000, 'Settings fetch timeout'),
              'Fetching user settings',
            ),
            this.withRetry(
              () => this.withTimeout(useUserStore().getUserOrganizations(), 15000, 'Organizations fetch timeout'),
              'Loading organizations',
            ),
          ]);
          this.steps[2].isCompleted = true;
        } catch (err) {
          this.handleStepError(2, 'Failed to setup session', err);
          return;
        }

        // Settings are now loaded — apply the backend language preference so a
        // fresh login lands on the server's language (boot couldn't, the token
        // didn't exist yet). Non-blocking: never let language hold up the flow.
        await this.applyBackendLanguage();

        // step 4: Subscription verification in parallel (informational only — never blocks access)
        // Both calls are independent: verifySubscription hits the subscription endpoint,
        // checkSubscriptionValidity fetches feature subscriptions and reconciles settings.
        // Both swallow their own errors internally, so allSettled here is purely defensive.
        await Promise.allSettled([
          this.withTimeout(this.verifySubscription(), 8000, 'Subscription verification timeout'),
          this.withTimeout(
            subscriptionUtil.methods.checkSubscriptionValidity(),
            8000,
            'Feature subscription check timeout',
          ),
        ]);
        this.steps[3].isCompleted = true;

        // DocNet WebSocket connects via boot/websocket.js (handles both refresh and fresh login)

        // step 5: Caching application data (background — not on the critical path)
        // Auto-accounting + ACL warm-up. Consumer pages (AutoAccounting/*) await
        // fetchLnAccountsPromise themselves; ACL is already fetched in step 2.
        this.cacheApplicationData().catch((err) => {
          logger.info('PrepareDashboard: Background cache failed (non-critical)', err);
        });
        this.steps[4].isCompleted = true;

        // step 6: Finalizing setup and redirecting
        try {
          useSubscriptionStore().subscriptionWindowClosed = false;
          this.steps[5].isCompleted = true;
          await this.restoreLanguagePreference();
          if (!this.userInteractedWithCarousel) {
            await this.performRedirect();
          }
        } catch (err) {
          this.handleStepError(5, 'Failed to finalize setup and redirect', err);
          return;
        }
      } catch (err) {
        // Fallback error handling
        this.handleGeneralError(
          'Unexpected error during dashboard preparation',
          err,
        );
      } finally {
        this.isInitializing = false;
        _mountCount = 0;
        if (this.timerInterval) {
          clearInterval(this.timerInterval);
        }
      }
    },

    handleStepError(stepIndex: number, _stepMessage: string, error: any) {
      this.hasFailedCritically = true;
      this.isInitializing = false;

      for (let i = stepIndex; i < this.steps.length; i++) {
        this.steps[i].hasError = true;
      }

      const apiError = ApiExceptions.getErrorMessage(error as dynamicObj);
      const userFriendlyMessage = this.getUserFriendlyErrorMessage(stepIndex, apiError);

      logger.error(`PrepareDashboard step ${stepIndex + 1} (${this.steps[stepIndex].stepName}) failed`, error);
      this.errorMessage = userFriendlyMessage;
      notify.error(userFriendlyMessage);
    },

    handleGeneralError(message: string, error: any) {
      const completedSteps = this.steps.filter((s) => s.isCompleted).length;
      for (let i = completedSteps; i < this.steps.length; i++) {
        this.steps[i].hasError = true;
      }

      const fullMessage = `${message}: ${ApiExceptions.getErrorMessage(error as dynamicObj)}`;
      logger.error('PrepareDashboard: General error', error);
      this.errorMessage = fullMessage;
      notify.error(fullMessage);
      this.$emit('setPrepareDashboardDlg', false);
    },

    async verifySubscription() {
      try {
        const subscription_store = useSubscriptionStore();
        await subscription_store.getSubscriptionFromServer();
        const subscriptions_data = subscription_store.getSubscription();
        if (isUndefinedOrNull(subscriptions_data)) {
          // CRITICAL: Never block access on dashboard - always allow with warning
          logger.info(
            'PrepareDashboard: No subscription data available, allowing access with warning',
          );
          return true;
        }
        return true;
      } catch (err) {
        // CRITICAL: Never block user access on prepare-dashboard
        // Log the error but allow access - subscription checks are informational only
        logger.error('Subscription verification encountered an error', err);
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        logger.info(
          `PrepareDashboard: Subscription verification failed, but allowing access anyway. Reason: ${msg}`,
        );
        return true;
      }
    },

    async cacheApplicationData() {
      await cacheDataAfterLogin();
      // Prefetch dashboard data so dashboard.vue loads instantly.
      useDashboardPreloadStore().prefetchDashboardData().catch((err) => {
        logger.info('PrepareDashboard: Dashboard prefetch failed (non-critical)', err);
      });
    },

    async performRedirect() {
      if (this.hasFailedCritically) return;

      try {
        if (this.isOAuthLoginRoute()) {
          await this.redirectForOAuthLogin();
          return;
        }

        const queryRedirect = this.$route?.query?.redirect as string | undefined;
        let finalUrl = queryRedirect || this.getPathFromStorage();
        if (finalUrl === '/prepare-dashboard' || finalUrl === this.$route.path) {
          finalUrl = '/dashboard';
        }

        await this.$router.push(finalUrl);
      } catch (error) {
        logger.error('PrepareDashboard: Redirect failed', error);
        this.hasFailedCritically = true;
        this.errorMessage = 'Redirect failed. Please use the login button to continue manually.';
        notify.error('Unable to redirect automatically. Please click "Back to Login" to continue.');
      }
    },

    getPathFromStorage(): string {
      const login_path = LocalStorage.getItem(_AFTER_LOGIN_ROUTE_KEY) as string;
      let path = login_path;
      if (!LocalStorage.has(_AFTER_LOGIN_ROUTE_KEY) || login_path === null || login_path === '') {
        path = '/dashboard';
      }
      LocalStorage.remove(_AFTER_LOGIN_ROUTE_KEY);
      return path;
    },

    isOAuthLoginRoute(): boolean {
      return this.$route.path === '/oauth/login';
    },

    async redirectForOAuthLogin(): Promise<void> {
      const token = (await userApiService.getToken()).replace('Bearer ', '');
      const org_id = getUserDetailFromkey('org_id');
      const url = api.insight_url + '/sso/polydocs/' + org_id + '?code=' + token;
      window.open(url);
    },

    onCarouselInteract() {
      this.userInteractedWithCarousel = true;
      logger.info('[PrepareDashboard] User interacted with video carousel — auto-redirect paused');
    },

    goToLogin() {
      this.$router.push('/login');
    },
    retrySetup() {
      // Reset all states for retry
      this.errorMessage = '';
      this.hasFailedCritically = false;
      this.isInitializing = false;
      this.showTimeoutWarning = false;
      this.userInteractedWithCarousel = false;

      // Reset all steps
      for (let i = 0; i < this.steps.length; i++) {
        this.steps[i].isCompleted = false;
        this.steps[i].hasError = false;
      }

      logger.info('PrepareDashboard: User requested setup retry');

      // Restart timer
      this.startTimer();

      // Retry the initialization
      setTimeout(() => {
        this.initPage();
      }, 500);
    },
    // Timeout wrapper for API calls
    withTimeout(
      promise: Promise<any>,
      timeoutMs: number,
      timeoutMessage: string,
    ): Promise<any> {
      return Promise.race([
        promise,
        new Promise((_, reject) => {
          setTimeout(() => {
            reject(new Error(timeoutMessage));
          }, timeoutMs);
        }),
      ]);
    },

    // Retry wrapper for API calls with exponential backoff
    async withRetry(
      apiCall: () => Promise<any>,
      stepName: string,
      maxRetries: number = 3,
    ): Promise<any> {
      let lastError: any;

      for (let attempt = 1; attempt <= maxRetries; attempt++) {
        try {
          logger.info(
            `PrepareDashboard: ${stepName} - Attempt ${attempt}/${maxRetries}`,
          );
          const result = await apiCall();
          if (attempt > 1) {
            logger.info(
              `PrepareDashboard: ${stepName} - Succeeded on attempt ${attempt}`,
            );
          }
          return result;
        } catch (error: any) {
          lastError = error;
          logger.warn(
            `PrepareDashboard: ${stepName} - Attempt ${attempt}/${maxRetries} failed:`,
            error,
          );
          // If this was the last attempt, throw the error
          if (attempt === maxRetries) {
            const errorMsg = ApiExceptions.getErrorMessage(error as dynamicObj);
            throw new Error(
              `${stepName} failed after ${maxRetries} attempts. Last error: ${errorMsg}`,
            );
          }

          // Wait before retry with exponential backoff
          const delay = Math.min(1000 * Math.pow(2, attempt - 1), 5000);
          logger.info(
            `PrepareDashboard: ${stepName} - Waiting ${delay}ms before retry ${attempt + 1}`,
          );
          await new Promise((resolve) => setTimeout(resolve, delay));
        }
      }

      throw lastError;
    },

    getUserFriendlyErrorMessage(stepIndex: number, apiError: string): string {
      const stepNames = [
        'securing your session',
        'loading your settings',
        'preparing your workspace',
        'confirming your access',
        'preparing your dashboard data',
        'finalizing setup',
      ];
      const stepName = stepNames[stepIndex] || 'processing';

      if (apiError.includes('timeout')) {
        return `Connection timeout while ${stepName}. Please check your internet connection and try again.`;
      }
      if (apiError.includes('Network Error') || apiError.includes('ERR_NETWORK')) {
        return `Network connection failed while ${stepName}. Please check your internet connection.`;
      }
      // Match by HTTP status and by the backend's token/session error strings
      // ("token is missing, invalid, or expired", "invalid_token", "User not
      // found") — a session revoked mid-setup (e.g. account deleted after the
      // token was issued) arrives as one of these without a literal "401"
      // (DOCB-13581).
      if (
        stepIndex <= 1 &&
        /401|403|Unauthorized|invalid_token|token is missing|User not found/i.test(
          apiError,
        )
      ) {
        return 'Authentication failed. Please log in again to continue.';
      }
      if (stepIndex === 3 && /subscription|expired/.test(apiError)) {
        return 'Your subscription is not valid or has expired. Please contact support.';
      }
      if (/50[0234]/.test(apiError)) {
        return `Server error while ${stepName}. Our servers may be temporarily unavailable. Please try again in a few minutes.`;
      }
      return `An error occurred while ${stepName}: ${apiError}`;
    },

    async restoreLanguagePreference() {
      try {
        const savedLanguagePreference = await useSettingStore().getUserBasedSettings(preferred_language_setting);
        if (savedLanguagePreference && savedLanguagePreference !== 'undefined' && savedLanguagePreference !== 'null') {
          LocalStorage.set(CONSTANTS.selected_language, savedLanguagePreference);
        }
      } catch (err) {
        logger.debug('[PrepareDashboard] Error restoring language preference:', err);
      }
    },
  },
  computed: {
    switchAnimationSrc(): string | null {
      if (!this.switchFrom || !this.switchTo) return null;
      return switchAnimationAsset(this.switchFrom, this.switchTo);
    },
    switchTargetLabel(): string {
      if (this.switchTo === 'us') return this.$t('login_auth_region_us') as string;
      if (this.switchTo === 'eu') return this.$t('login_auth_region_eu') as string;
      return '';
    },
    progressValue() {
      const completedSteps = this.steps.filter(
        (step) => step.isCompleted,
      ).length;
      return this.steps.length > 0 ? completedSteps / this.steps.length : 0;
    },
    progressSubtitle() {
      const completedSteps = this.steps.filter(
        (step) => step.isCompleted,
      ).length;
      if (completedSteps === 0) {
        return this.$t('loading');
      } else if (completedSteps < this.steps.length) {
        return this.$t('step_x_of_y', { current: completedSteps + 1, total: this.steps.length });
      } else {
        return this.$t('dashboard_setup_complete');
      }
    },
    currentStepText() {
      const currentStep = this.steps.find((s, i) => this.isCurrentStep(i));
      return currentStep ? this.$t(currentStep.stepName) : '';
    },
    isTestEnvironment(): boolean {
      // Detect if running in Playwright or other automation
      return (
        typeof window !== 'undefined' &&
        (!!(window as any).Cypress ||
          !!(window as any)._playwright_test ||
          navigator.userAgent.includes('Playwright'))
      );
    },
  },
});
</script>

